noncomputable def congr {k : Type u} [Field k] {C C' : Over (Spec (.of k))}
    [IsProper C.hom] [SmoothOfRelativeDimension 1 C.hom] [GeometricallyIrreducible C.hom]
    [IsProper C'.hom] [SmoothOfRelativeDimension 1 C'.hom] [GeometricallyIrreducible C'.hom]
    (e : C ≅ C') :
    (.mk (Jacobian C) : Grp (Over (Spec (.of k)))) ≅ .mk (Jacobian C') :=
  let j : (⟨C⟩ : Curve k) ≅ ⟨C'⟩ :=
    { hom := e.hom, inv := e.inv, hom_inv_id := e.hom_inv_id, inv_hom_id := e.inv_hom_id }
  (Jacobian.functor k).mapIso j.symm.op

private def invSig (p : Σ E : Algebra.EtaleCover A, descentClasses C E) :
    Σ E : Algebra.EtaleCover A, descentClasses C E :=
  ⟨p.1, p.2⁻¹⟩

private def mapSig (f : X ⟶ Y) (p : Σ 𝒰 : Y.PointedCover, Y.unitsH1 𝒰) :
    Σ 𝒰 : X.PointedCover, X.unitsH1 𝒰 :=
  ⟨p.1.pullback f, f.pullbackUnitsH1 p.1 p.2⟩

private def mulSig (p q : Σ 𝒰 : X.PointedCover, X.unitsH1 𝒰) :
    Σ 𝒰 : X.PointedCover, X.unitsH1 𝒰 :=
  ⟨p.1 ⊓ q.1, unitsRes inf_le_left p.2 * unitsRes inf_le_right q.2⟩

lemma Hom.le_preimage_inf (f : X.Hom Y) {U : X.Opens} {V₁ V₂ : Y.Opens}
    (h₁ : U ≤ f ⁻¹ᵁ V₁) (h₂ : U ≤ f ⁻¹ᵁ V₂) : U ≤ f ⁻¹ᵁ (V₁ ⊓ V₂) :=
  fun _ hx ↦ ⟨h₁ hx, h₂ hx⟩

def unitsAppLE (f : X.Hom Y) (V : Y.Opens) (U : X.Opens) (e : U ≤ f ⁻¹ᵁ V) :
    Γ(Y, V)ˣ →* Γ(X, U)ˣ :=
  Units.map (f.appLE V U e).hom

private lemma inv_mul_mul_inv_cancel {G : Type u} [CommGroup G] (a r b : G) :
    a⁻¹ * (a * r * b⁻¹) = r * b⁻¹ := by
  rw [mul_assoc, inv_mul_cancel_left]

private lemma coe_unitsRestrict {W U : X.Opens} (h : W ≤ U) (u : Γ(X, U)ˣ) :
    (X.unitsRestrict h u : Γ(X, W)) = (X.presheaf.map (homOfLE h).op).hom (u : Γ(X, U)) := by
  simp only [Scheme.unitsRestrict, Units.coe_map, MonoidHom.coe_coe]

lemma unitsCocycle_ext {𝒰 : X.PointedCover} {γ δ : X.unitsCocycle 𝒰}
    (h : ∀ i j, unitsEvInf γ i j = unitsEvInf δ i j) : γ = δ :=
  OneCocycle.ext_evInf h

def unitsEvInf {𝒰 : X.PointedCover} (γ : X.unitsCocycle 𝒰) (i j : X) :
    Γ(X, 𝒰.opens i ⊓ 𝒰.opens j)ˣ :=
  γ.evInf i j

def doubleInl (E : Algebra.EtaleCover A) :
    E.Carrier →ₐ[k] E.Carrier ⊗[A] E.Carrier :=
  Algebra.TensorProduct.includeLeft

def doubleInr (E : Algebra.EtaleCover A) :
    E.Carrier →ₐ[k] E.Carrier ⊗[A] E.Carrier :=
  (Algebra.TensorProduct.includeRight).restrictScalars k

private noncomputable def resLeft [Y.Over (Spec (.of k))] :
    Γ(Y, U₀) →ₗ[k] Γ(Y, U₀ ⊓ U₁) :=
  ((Y.moduleKSheaf k).obj.map (homOfLE (inf_le_left : U₀ ⊓ U₁ ≤ U₀)).op).hom

private noncomputable def resRight [Y.Over (Spec (.of k))] :
    Γ(Y, U₁) →ₗ[k] Γ(Y, U₀ ⊓ U₁) :=
  ((Y.moduleKSheaf k).obj.map (homOfLE (inf_le_right : U₀ ⊓ U₁ ≤ U₁)).op).hom

private noncomputable def secRes {U V : X.Opens} (h : V ≤ U) :
    G.obj.obj (op U) →ₗ[k] G.obj.obj (op V) :=
  (G.obj.map (homOfLE h).op).hom

private lemma secRes_moduleKSheaf [X.Over (Spec (.of k))] {U V : X.Opens} (h : V ≤ U)
    (s : Γ(X, U)) :
    secRes (X.moduleKSheaf k) h s = X.resHom h s := rfl

lemma OneCohomologyRelation.res {γ₁ γ₂ : OneCochain G U} {α : ZeroCochain G U}
    (h : OneCohomologyRelation γ₁ γ₂ α) (f : ∀ i, V i ⟶ U i) :
    OneCohomologyRelation (γ₁.res f) (γ₂.res f) (fun i ↦ G.map (f i).op (α i)) := by
  intro i j T a b
  simpa [← ConcreteCategory.comp_apply, ← Functor.map_comp, ← op_comp]
    using h i j (a ≫ f i) (b ≫ f j)
